# identity.get, clock.get, advert.send and device.reboot (docs/contract/OPERATIONS.md section 5.1): undo each rule they add
DO=sim/tests/test_device_ops.py
mutate reboot_class_console src/helpers/iface/ConsoleIface.cpp '                      : op.priv == PRIV_REBOOT ? Cli::C_REBOOT' '' "$DO::test_a_standalone_server_may_be_rebooted_by_its_verified_broker"
mutate reboot_class_companion examples/companion_radio/MeconIface.cpp '                      : op.priv == PRIV_REBOOT ? Cli::C_REBOOT' '' "$DO::test_a_standalone_companion_may_be_rebooted_by_its_verified_broker"
mutate reboot_remote_unsigned_console src/helpers/iface/ConsoleIface.cpp '  ctx.enrolled = (cls == Cli::C_READ || cls == Cli::C_REBOOT) && s->_auth.enrolled();' '  ctx.enrolled = cls == Cli::C_READ && s->_auth.enrolled();' "$DO::test_an_unsigned_reboot_over_a_servers_broker_is_refused_once_enrolled[repeater_wifi]"
mutate reboot_remote_unsigned_companion examples/companion_radio/MeconIface.cpp '  ctx.enrolled = (cls == Cli::C_READ || cls == Cli::C_REBOOT) && self->_auth.enrolled();' '  ctx.enrolled = cls == Cli::C_READ && self->_auth.enrolled();' "$DO::test_an_unsigned_reboot_over_mqtt_is_refused_once_enrolled"
mutate reboot_preauth_denied src/helpers/iface/DeployAuth.cpp '!plain_read && op.priv != PRIV_REBOOT && ' '!plain_read && ' "$DO::test_device_reboot_answers_then_reboots_and_the_unsigned_cable_keeps_it[room_server]"
mutate reboot_not_scheduled src/helpers/iface/ConsoleIface.cpp 'Status opDeviceReboot(OpContext& c) { self(c)->rebootSoon(); return ST_OK; }' 'Status opDeviceReboot(OpContext& c) { (void)c; return ST_OK; }' "$DO::test_device_reboot_answers_then_reboots_and_the_unsigned_cable_keeps_it[repeater]"
mutate clock_get_needs_a_job src/helpers/deployment/DepWrapper.cpp '"identity.rotation", "clock.get", "job.get"' '"identity.rotation", "job.get"' "$DO::test_identity_and_clock_are_plain_reads_that_agree_with_hello[repeater]"
mutate advert_never_floods_console src/helpers/iface/ConsoleIface.cpp 'flood ? "advert" : "advert.zerohop"' '"advert.zerohop"' "$DO::test_advert_send_goes_on_the_air_zero_hop_or_flooded[repeater]"
mutate advert_never_floods_companion examples/companion_radio/MeconIface.cpp '  if (!self(c)->mesh()->sendSelfAdvert(flood)) { c.error = "busy"; return ST_FAILED; }' '  if (!self(c)->mesh()->sendSelfAdvert(false)) { c.error = "busy"; return ST_FAILED; }' "$DO::test_advert_send_goes_on_the_air_zero_hop_or_flooded[companion_standalone]"
mutate identity_get_needs_a_job src/helpers/deployment/DepWrapper.cpp '"identity.get", "identity.rotation", "clock.get"' '"identity.rotation", "clock.get"' "$DO::test_identity_and_clock_are_plain_reads_that_agree_with_hello[companion_standalone]"
mutate region_list_needs_a_job src/helpers/deployment/DepWrapper.cpp '                                       "region.list" };' '                                       "none" };' "$DO::test_region_list_is_a_plain_read_once_enrolled"
mutate mqtt_every_write_slow src/helpers/mqtt/MqttController.cpp '  if (ms >= 1000) _slow_writes++;' '  _slow_writes++;' "$DO::test_the_connectivity_event_times_the_broker_writes"
mutate clock_set_backwards_companion examples/companion_radio/MyMesh.cpp '  if (secs < getRTCClock()->getCurrentTime()) return false;' '' "$DO::test_clock_set_moves_the_clock_forward_only[companion_standalone]"
mutate acl_role_lost src/helpers/iface/ConsoleIface.cpp '    w.key("role"); w.str(ACL_ROLES[perms & 3]);' '    w.key("role"); w.str(ACL_ROLES[0]);' "$DO::test_the_remote_admin_acl_is_listed_and_set[repeater]"
mutate acl_put_any_role src/helpers/iface/ConsoleIface.cpp '  if (perms < 0) return ST_INVALID;' '  if (perms < 0) perms = 3;' "$DO::test_the_remote_admin_acl_is_listed_and_set[repeater]"
mutate password_set_over_broker src/helpers/iface/ConsoleIface.cpp '  if (m->onBroker()) { c.error = "not-over-this-link"; return ST_REFUSED; }' '' "$DO::test_password_set_is_refused_over_the_broker"
mutate password_set_truncates src/helpers/iface/ConsoleIface.cpp '  if (strlen(pw) > 15) { wipe(pw, sizeof(pw)); c.error = "too-long"; return ST_INVALID; }   // the native field holds 15' '' "$DO::test_password_set_is_write_only_and_console_only"
